import { Accessor, createMemo, splitProps, type JSX } from "solid-js";

import { NavigateInputEvent } from "#core/ui/input/input-support.js";
import { Activatable, ActivatableProps } from "#core/ui-next/components/activatable.jsx";
import { ArrowButton } from "#core/ui-next/components/arrow-button.jsx";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { NavHelp } from "#core/ui-next/components/nav-help.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

export interface SelectorSmallProps<T> extends ActivatableProps {
	items: {
		name: string;
		description: string;
		value: T;
	}[];

	selectedValue: Accessor<T>;
	setSelectedValue: (value: T) => void;
	style?: JSX.CSSProperties;
	disabled?: boolean;
	fixedWidth?: string;
	previousActionKey?: string;
	nextActionKey?: string;
	arrowClass?: string;
}

function SelectorSmallComponent<T>(props: SelectorSmallProps<T>) {
	const [local, other] = splitProps(props, ["class", "items", "selectedValue", "setSelectedValue"]);

	const selectedItem = createMemo(() => local.items?.find((i) => i.value == local.selectedValue()) ?? local.items[0]);
	const selectedIndex = createMemo(() => local.items?.findIndex((i) => i.value == local.selectedValue()));

	const previousActionKey = createMemo(() => props.previousActionKey ?? "nav-previous");
	const nextActionKey = createMemo(() => props.nextActionKey ?? "nav-next");

	const audioTrigger = useAudio();

	function selectNext() {
		if (!props.disabled) {
			let newIndex = selectedIndex() + 1;
			if (newIndex >= local.items.length) {
				newIndex = 0;
			}
			local.setSelectedValue(local.items[newIndex].value);
		}
	}

	function selectPrevious() {
		if (!props.disabled) {
			let newIndex = selectedIndex() - 1;
			if (newIndex < 0) {
				newIndex = local.items.length - 1;
			}
			local.setSelectedValue(local.items[newIndex].value);
		}
	}

	function onNavigate(navigationEvent: NavigateInputEvent) {
		if (navigationEvent.detail.status == InputActionStatuses.FINISH) {
			if (navigationEvent.detail.name == previousActionKey()) {
				selectPrevious();
				audioTrigger("nav-previous");
				navigationEvent.preventDefault();
				navigationEvent.stopPropagation();
			} else if (navigationEvent.detail.name == nextActionKey()) {
				selectNext();
				audioTrigger("nav-next");
				navigationEvent.preventDefault();
				navigationEvent.stopPropagation();
			}
		}
	}

	return (
		<Tooltip.Text
			text={selectedItem()?.description}
			bodyClass="flex flex-row justify-center"
		>
			<AudioContextProvider segment="Option">
				<Activatable
					{...other}
					class={`flex flex-row flex-auto items-center justify-center relative group ${local.class || ""} ${props.disabled ? "opacity-40" : ""}`}
					on:navigate-input={onNavigate}
				>
					<ArrowButton
						right={false}
						disableFocus={true}
						onActivate={selectPrevious}
						class={props.arrowClass ?? ""}
					/>
					<NavHelp
						actionName={previousActionKey()}
						class="mx-1 opacity-0 group-focus\:opacity-100"
					/>

					<div
						class={`flex-auto flex flex-col items-center justify-center ${props.fixedWidth ? "font-fit-shrink" : ""}`}
						style={{ width: props.fixedWidth }}
					>
						<L10n.Compose text={selectedItem()?.name ?? ""} />
					</div>

					<NavHelp
						actionName={nextActionKey()}
						class="mx-1 opacity-0 group-focus\:opacity-100"
					/>
					<ArrowButton
						right={true}
						disableFocus={true}
						onActivate={selectNext}
						class={props.arrowClass ?? ""}
					/>
					<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />
				</Activatable>
			</AudioContextProvider>
		</Tooltip.Text>
	);
}

export const SelectorSmall = ComponentRegistry.register("SelectorSmall", SelectorSmallComponent);
